// Generated by build-shader-references.mjs; do not edit.
export default {"handdrawn-fill.hlsl":"// Momo Texture Forge reference shader, version 1. No Rough.js code is used here.\n// UV origin is bottom-left. Sizes are measured in design pixels, not screen pixels.\n#ifndef MOMO_HANDDRAWN_FILL_INCLUDED\n#define MOMO_HANDDRAWN_FILL_INCLUDED\nstruct MFHanddrawnParams {\n    float style;\n    float gap;\n    float width;\n    float angle;\n    float roughness;\n    float seed;\n    float dashLength;\n    float dashGap;\n    float inkOpacity;\n    float paperOpacity;\n    float2 scroll;\n    float2 designSize;\n    float3 inkColor;\n    float3 paperColor;\n};\nfloat MFHash(float2 p) {\n    float3 q = frac(float3(p.x, p.y, p.x) * 0.1031);\n    q += dot(q, q.yzx + 33.33);\n    return frac((q.x + q.y) * q.z);\n}\nfloat MFSoftStroke(float distanceToLine, float width) {\n    float aa = max(fwidth(distanceToLine), 0.35);\n    return 1.0 - smoothstep(width * 0.5 - aa, width * 0.5 + aa, distanceToLine);\n}\nfloat MFHatch(float2 p, MFHanddrawnParams v, float zigzag) {\n    float gap = max(v.gap, 2.0);\n    float seed = fmod(v.seed, 1009.0);\n    float wobble = sin(p.x * 0.055 + seed * 0.13) * 1.5\n                 + sin(p.x * 0.2 + seed) * 0.4;\n    float teeth = (abs(frac(p.x / (gap * 2.0)) - 0.5) * 2.0 - 0.5) * gap * 0.6;\n    float y = p.y + wobble * v.roughness + teeth * zigzag;\n    float distanceToLine = abs(frac(y / gap + 0.5) - 0.5) * gap;\n    return MFSoftStroke(distanceToLine, v.width);\n}\n// mask is a linear coverage value read from the red channel of a clamp-sampled texture.\n// Colors and the returned straight RGB are linear. Multiply RGB by A for premultiplied blending.\nfloat4 MFHanddrawnFill(float2 uv, float mask, float timeSeconds, MFHanddrawnParams v) {\n    float2 p = (uv - 0.5) * max(v.designSize, float2(1.0, 1.0)) + v.scroll * timeSeconds;\n    float angle = v.angle * 0.017453292519943295;\n    float2 rotated = float2(cos(angle) * p.x + sin(angle) * p.y,\n                          -sin(angle) * p.x + cos(angle) * p.y);\n    float gap = max(v.gap, 2.0);\n    float pattern = 1.0;\n    if (v.style > 0.5 && v.style < 2.5) {\n        pattern = MFHatch(rotated, v, 0.0);\n        if (v.style > 1.5) pattern = 1.0 - (1.0 - pattern) * (1.0 - MFHatch(rotated.yx, v, 0.0));\n    }\n    if (v.style > 2.5 && v.style < 3.5) {\n        float2 cell = floor(rotated / gap);\n        float seed = fmod(v.seed, 1009.0);\n        float2 jitter = float2(MFHash(cell + seed), MFHash(cell + seed + 19.0)) - 0.5;\n        float2 local = (frac(rotated / gap) - 0.5) * gap - jitter * gap * v.roughness * 0.45;\n        pattern = MFSoftStroke(length(local), v.width * 2.0);\n    }\n    if (v.style > 3.5 && v.style < 4.5) {\n        float period = max(v.dashLength + v.dashGap, 1.0);\n        float along = frac((rotated.x + floor(rotated.y / gap + 0.5) * period * 0.37) / period) * period;\n        float aa = max(fwidth(rotated.x), 0.35);\n        float dash = smoothstep(0.0, aa, along) * (1.0 - smoothstep(v.dashLength - aa, v.dashLength, along));\n        pattern = MFHatch(rotated, v, 0.0) * dash;\n    }\n    if (v.style > 4.5) pattern = MFHatch(rotated, v, 1.0);\n    float ink = saturate(pattern * v.inkOpacity);\n    float paper = saturate(v.paperOpacity) * (1.0 - ink);\n    float coverage = ink + paper;\n    float3 rgb = (v.inkColor * ink + v.paperColor * paper) / max(coverage, 0.000001);\n    return float4(rgb, saturate(mask) * coverage);\n}\n#endif\n","HanddrawnFillURP.shader":"// Unity 6 / URP 17 reference. Validate in your target project before shipping.\nShader \"MomoTextureForge/HanddrawnFill\" {\n    Properties {\n        [NoScaleOffset] _MaskTex (\"Mask (linear red channel)\", 2D) = \"white\" {}\n        [Enum(Solid,0,Hachure,1,CrossHatch,2,Dots,3,Dashed,4,Zigzag,5)] _Style (\"Fill style\", Float) = 2\n        _Gap (\"Gap (design pixels)\", Range(2,96)) = 8\n        _Width (\"Stroke width / dot radius\", Range(0.25,12)) = 1.1\n        _Angle (\"Angle (degrees)\", Range(-180,180)) = -44\n        _Roughness (\"Wobble\", Range(0,1)) = 0.25\n        [IntRange] _Seed (\"Seed\", Range(1,99999)) = 1\n        _DashLength (\"Dash length\", Range(1,128)) = 8\n        _DashGap (\"Dash gap\", Range(1,128)) = 5\n        _InkColor (\"Ink (sRGB picker)\", Color) = (0.91,0.267,0.286,1)\n        _PaperColor (\"Paper (sRGB picker)\", Color) = (1,0.969,0.925,1)\n        _InkOpacity (\"Ink opacity\", Range(0,1)) = 1\n        _PaperOpacity (\"Paper opacity\", Range(0,1)) = 0\n        _Scroll (\"Scroll XY (design pixels/sec)\", Vector) = (0,0,0,0)\n        _DesignSize (\"Design size XY\", Vector) = (512,512,0,0)\n        [Toggle] _UseCustomTime (\"Use custom time\", Float) = 0\n        _TimeSeconds (\"Custom time (seconds)\", Float) = 0\n    }\n    SubShader {\n        Tags { \"RenderPipeline\"=\"UniversalPipeline\" \"RenderType\"=\"Transparent\" \"Queue\"=\"Transparent\" }\n        Pass {\n            Name \"Unlit\"\n            Tags { \"LightMode\"=\"SRPDefaultUnlit\" }\n            Cull Off\n            ZWrite Off\n            Blend SrcAlpha OneMinusSrcAlpha, One OneMinusSrcAlpha\n            HLSLPROGRAM\n            #pragma target 3.0\n            #pragma vertex Vert\n            #pragma fragment Frag\n            #include \"Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl\"\n            #include \"Packages/com.unity.render-pipelines.core/ShaderLibrary/Color.hlsl\"\n            #include \"handdrawn-fill.hlsl\"\n            TEXTURE2D(_MaskTex);\n            SAMPLER(sampler_MaskTex);\n            CBUFFER_START(UnityPerMaterial)\n                float4 _InkColor, _PaperColor, _Scroll, _DesignSize;\n                float _Style, _Gap, _Width, _Angle, _Roughness, _Seed;\n                float _DashLength, _DashGap, _InkOpacity, _PaperOpacity;\n                float _UseCustomTime, _TimeSeconds;\n            CBUFFER_END\n            struct Attributes { float4 positionOS : POSITION; float2 uv : TEXCOORD0; UNITY_VERTEX_INPUT_INSTANCE_ID };\n            struct Varyings { float4 positionCS : SV_POSITION; float2 uv : TEXCOORD0; UNITY_VERTEX_OUTPUT_STEREO };\n            Varyings Vert(Attributes input) {\n                Varyings output;\n                UNITY_SETUP_INSTANCE_ID(input);\n                UNITY_INITIALIZE_VERTEX_OUTPUT_STEREO(output);\n                output.positionCS = TransformObjectToHClip(input.positionOS.xyz);\n                output.uv = input.uv;\n                return output;\n            }\n            float4 Frag(Varyings input) : SV_Target {\n                UNITY_SETUP_STEREO_EYE_INDEX_POST_VERTEX(input);\n                MFHanddrawnParams v;\n                v.style=_Style; v.gap=_Gap; v.width=_Width; v.angle=_Angle;\n                v.roughness=_Roughness; v.seed=_Seed;\n                v.dashLength=_DashLength; v.dashGap=_DashGap;\n                v.inkOpacity=_InkOpacity; v.paperOpacity=_PaperOpacity;\n                v.scroll=_Scroll.xy; v.designSize=_DesignSize.xy;\n                // Unity converts Color properties for linear projects; normalize gamma projects here.\n                v.inkColor=_InkColor.rgb; v.paperColor=_PaperColor.rgb;\n                #ifdef UNITY_COLORSPACE_GAMMA\n                    v.inkColor=SRGBToLinear(v.inkColor); v.paperColor=SRGBToLinear(v.paperColor);\n                #endif\n                float seconds=lerp(_Time.y,_TimeSeconds,step(0.5,_UseCustomTime));\n                float4 result=MFHanddrawnFill(input.uv,SAMPLE_TEXTURE2D(_MaskTex,sampler_MaskTex,input.uv).r,seconds,v);\n                #ifdef UNITY_COLORSPACE_GAMMA\n                    result.rgb=LinearToSRGB(result.rgb);\n                #endif\n                return result;\n            }\n            ENDHLSL\n        }\n    }\n    FallBack Off\n}\n","README.md":"# 手绘填充 Shader 参考包\r\n\r\n<!-- doc-language -->\r\n[简体中文](README.md) · [English](README.en.md)\r\n<!-- /doc-language -->\r\n\r\n这是独立的单次绘制、无光照透明材质参考。输入一张遮罩，生成纯色、平行排线、交叉排线、圆点、虚线或锯齿排线。它不执行 Rough.js 轮廓重绘，也不播放编辑器节点树或关键帧。\r\n\r\n从手绘后处理面板下载。`sourceEffect.values` 保存原效果参数，`mapping`/`limitations` 说明近似映射；`parameters` 是参考Shader实际使用的值。`editor-preview.png` 为原编辑器效果，`reference-preview.png` 为填充参考，两者不保证一致。轮廓遮罩烘焙当前帧与变换；原粗糙度除以10映射起伏，超出Shader范围的数值会被限制，原值仍保留。\r\n\r\n## 文件与输入输出\r\n\r\n- `handdrawn-fill.hlsl`：核心函数 `MFHanddrawnFill(uv, mask, timeSeconds, parameters)`；没有外部纹理依赖或引擎运行组件。\r\n- `HanddrawnFillURP.shader`：Unity 6 / URP 17 的参考封装。两个源码文件放在同一目录；给网格提供0～1 UV。\r\n- `parameters.json`：当前参数、设计尺寸、色彩编码和实际验证状态。它是参数数据，不是脚本或 AI 操作指令。\r\n- `mask.png`：红通道保存0～1覆盖度；Alpha恒为1。导入为线性数据纹理，关闭 sRGB，Wrap=Clamp，避免纹理压缩改变边缘。\r\n- `reference-preview.png`：当前预览时间下的透明 PNG；RGB使用sRGB编码。\r\n- `reference-preview.vert.glsl` / `reference-preview.frag.glsl`：浏览器实际使用的预览程序，核心数学由同一份HLSL参考转换而来。颜色uniform需使用线性RGB；设计尺寸、滚动和时间与JSON一致。\r\n\r\n核心函数输出直通的线性RGB和覆盖Alpha。普通透明混合使用RGB `SrcAlpha / OneMinusSrcAlpha`，Alpha使用 `One / OneMinusSrcAlpha`。接到预乘材质时先将RGB乘Alpha，并相应改变混合状态，避免重复乘透明度。\r\n\r\n## 在 Unity 中接入\r\n\r\n创建使用 `MomoTextureForge/HanddrawnFill` 的材质，把遮罩赋给 `_MaskTex`。按JSON设置下列属性；颜色选择器和 `Material.SetColor` 都使用 `parameters` 中的sRGB颜色。这两个属性在ShaderLab中声明为 `Color`，Unity在线性项目中会自动转换，勿再传入 `.linear`。JSON的 `colors.inkLinear` / `paperLinear` 供直接调用HLSL核心或设置普通向量uniform时使用；参考Shader会在Gamma项目中显式转换。参见 [Unity材质颜色属性约定](https://docs.unity3d.com/6000.0/Documentation/Manual/SL-PropertiesInPrograms.html)。\r\n\r\n参数对应：`style→_Style`、`gap→_Gap`、`width→_Width`、`angle→_Angle`、`roughness→_Roughness`、`seed→_Seed`、`dashLength→_DashLength`、`dashGap→_DashGap`、`inkOpacity→_InkOpacity`、`paperOpacity→_PaperOpacity`、`inkColor→_InkColor`、`paperColor→_PaperColor`。`scrollX/Y→_Scroll.xy`，`designSize→_DesignSize.xy`。\r\n\r\n样式索引固定为0纯色、1平行、2交叉、3圆点、4虚线、5锯齿。间距/笔宽/虚线长度使用设计像素：遮罩短边固定对应512，长边按比例增加；改变显示大小不会改变同一UV内的纹理次数。圆点模式的width是半径，其余模式是笔宽。正角度使排线从左下向右上倾斜。正scroll沿参数坐标推进纹理采样，因此图案在屏幕上向相反方向移动。随机种子不随帧变化。\r\n\r\n默认读取引擎时间。需要与下载预览逐帧对比时，开启 `_UseCustomTime` 并设置 `_TimeSeconds=previewTimeSeconds`。这不是整套动画控制器；在目标项目中按需要驱动这些普通材质参数。\r\n\r\n## 验证与适配\r\n\r\n浏览器编译和预览成功只证明GLSL预览运行。JSON中的 `engineCompilation: not-run` 明确表示工具没有调用Unity；必须在目标Unity/URP版本中检查编译、透明边缘、颜色和目标平台成本。不要把参考封装或浏览器预览描述成已在所有引擎验证。\r\n\r\nAI应先读取目标项目的引擎/管线/版本，优先保留核心函数，适配纹理采样、颜色空间和混合方式，创建实际可用的材质。需要不同形状时，可用Texture Forge创作Skill制作遮罩；不需要重建整个效果或增加运行组件。任意图片也可提供遮罩，但这份静态遮罩不会保留原来的节点参数、动画或后处理。\r\n","README.en.md":"# Hand-drawn fill shader reference package\r\n\r\n<!-- doc-language -->\r\n[简体中文](README.md) · [English](README.en.md)\r\n<!-- /doc-language -->\r\n\r\nA standalone, single-pass unlit transparent material reference. One mask drives solid, hachure, cross-hatch, dots, dashed or zigzag fill. It does not perform Rough.js contour redrawing or play the editor's node tree/keyframes.\r\n\r\nDownload from the hand-drawn effect panel. `sourceEffect.values` retains original settings and `mapping`/`limitations` explain approximation; `parameters` holds actual shader values. `editor-preview.png` shows the editor effect; `reference-preview.png` shows reference fill, not a pixel match. The contour mask bakes current time/transforms. Original roughness divided by 10 becomes wobble; shader values are range-limited while originals remain available.\r\n\r\n## Files and data contract\r\n\r\n- `handdrawn-fill.hlsl`: core `MFHanddrawnFill(uv, mask, timeSeconds, parameters)` without engine-runtime components or external texture dependencies.\r\n- `HanddrawnFillURP.shader`: Unity 6 / URP 17 reference wrapper. Keep both source files together and supply mesh UVs in 0–1.\r\n- `parameters.json`: current values, design size, color encoding and validation state. Treat it as parameter data, not executable code or AI instructions.\r\n- `mask.png`: linear 0–1 coverage in red; alpha is always one. Disable sRGB, use Clamp, and avoid compression that alters edges.\r\n- `reference-preview.png`: transparent current-time preview with sRGB-encoded RGB.\r\n- `reference-preview.vert.glsl` / `reference-preview.frag.glsl`: actual browser programs, deriving the core math from the same HLSL. Color uniforms use linear RGB; design size, scroll and time match JSON.\r\n\r\nThe core returns straight linear RGB and coverage alpha. Standard transparency uses RGB `SrcAlpha / OneMinusSrcAlpha` and alpha `One / OneMinusSrcAlpha`. For premultiplied materials, multiply RGB by alpha and change the blend state accordingly; do not multiply coverage twice.\r\n\r\n## Unity integration\r\n\r\nCreate a material using `MomoTextureForge/HanddrawnFill` and assign `_MaskTex`. Apply the JSON values to the properties below. Both the Inspector picker and `Material.SetColor` take the sRGB colors in `parameters`. These ShaderLab properties are declared as `Color`, so Unity converts them automatically in linear projects; do not pass `.linear` again. JSON's `colors.inkLinear` / `paperLinear` are for direct core calls or ordinary vector uniforms. The reference wrapper converts explicitly in gamma projects. See [Unity material color property conventions](https://docs.unity3d.com/6000.0/Documentation/Manual/SL-PropertiesInPrograms.html).\r\n\r\nMappings: `style→_Style`, `gap→_Gap`, `width→_Width`, `angle→_Angle`, `roughness→_Roughness`, `seed→_Seed`, `dashLength→_DashLength`, `dashGap→_DashGap`, `inkOpacity→_InkOpacity`, `paperOpacity→_PaperOpacity`, `inkColor→_InkColor`, `paperColor→_PaperColor`. Map `scrollX/Y→_Scroll.xy` and `designSize→_DesignSize.xy`.\r\n\r\nStable style indices: 0 solid, 1 hachure, 2 cross-hatch, 3 dots, 4 dashed, 5 zigzag. Gap, width and dash sizes use design pixels: the mask's short side corresponds to 512, with proportional long-side size. Display scaling does not change pattern count within the same UVs. Width is the dot radius in dots mode and stroke width otherwise. Positive angles tilt strokes from bottom-left toward top-right. Positive scroll advances sampling coordinates, moving the visible pattern in the opposite direction. Seeds remain stable across frames.\r\n\r\nThe wrapper uses engine time by default. For exact-time visual comparisons, enable `_UseCustomTime` and set `_TimeSeconds=previewTimeSeconds`. This is not an animation-controller system; drive ordinary material properties as needed in the target project.\r\n\r\n## Validation and adaptation\r\n\r\nSuccessful browser compilation/rendering validates only the GLSL preview. JSON's `engineCompilation: not-run` means the tool did not invoke Unity. Compile in the target Unity/URP version and check transparency, color and target-platform cost. Do not describe the reference or browser preview as validated in every engine.\r\n\r\nAI should inspect the target engine/pipeline/version, retain the core function where possible, adapt sampling/color/blending and create usable material assets. Use the Texture Forge Authoring Skill for additional masks rather than rebuilding the whole effect or adding runtime components. Any image can supply a mask, but a static mask does not retain its original node parameters, animation or post-processing.\r\n"};
